const setDirectoryReviewEmailsDisabled = `-- name: SetDirectoryReviewEmailsDisabled :one
INSERT INTO directory_review_org_states (organization_id, baseline_at, emails_disabled_at)
VALUES ($1, clock_timestamp(), CASE WHEN $2::boolean THEN clock_timestamp() END)
ON CONFLICT (organization_id) DO UPDATE
SET emails_disabled_at = CASE
      WHEN $2::boolean THEN COALESCE(directory_review_org_states.emails_disabled_at, clock_timestamp())
    END,
    updated_at = clock_timestamp()
RETURNING emails_disabled_at
`

type SetDirectoryReviewEmailsDisabledParams struct {
	OrganizationID string
	Disabled       bool
}

// Turns directory review emails off or on. Creates the organization's review
// state if the sweep has not yet, with the baseline it would record.
func (q *Queries) SetDirectoryReviewEmailsDisabled(ctx context.Context, arg SetDirectoryReviewEmailsDisabledParams) (pgtype.Timestamptz, error) {
	row := q.db.QueryRow(ctx, setDirectoryReviewEmailsDisabled, arg.OrganizationID, arg.Disabled)
	var emails_disabled_at pgtype.Timestamptz
	err := row.Scan(&emails_disabled_at)
	return emails_disabled_at, err
}

const supersedeDirectoryReviewItems = `-- name: SupersedeDirectoryReviewItems :many
UPDATE directory_review_items AS i
SET state = 'superseded',
    resolved_at = clock_timestamp(),
    updated_at = clock_timestamp()
WHERE i.organization_id = $1
  AND i.state = 'pending'
  AND ($2::uuid IS NULL OR i.directory_group_id = $2::uuid)
  AND ($3::text IS NULL OR i.attribute_key = $3::text)
  AND ($4::text IS NULL OR i.attribute_value = $4::text)
  AND (
    CASE
      WHEN i.directory_group_id IS NOT NULL THEN
        CASE i.kind
          WHEN 'new_group' THEN
            EXISTS (
              SELECT 1 FROM directory_role_mappings AS drm
              WHERE drm.organization_id = i.organization_id
                AND drm.directory_group_id = i.directory_group_id
                AND drm.deleted IS FALSE
            )
            OR NOT EXISTS (
              SELECT 1 FROM directory_groups AS dg
              WHERE dg.organization_id = i.organization_id
                AND dg.id = i.directory_group_id
                AND dg.deleted IS FALSE
                AND dg.workos_deleted IS FALSE
            )
          WHEN 'source_missing' THEN
            EXISTS (
              SELECT 1 FROM directory_groups AS dg
              WHERE dg.organization_id = i.organization_id
                AND dg.id = i.directory_group_id
                AND dg.deleted IS FALSE
                AND dg.workos_deleted IS FALSE
            )
            OR NOT EXISTS (
              SELECT 1 FROM directory_role_mappings AS drm
              WHERE drm.organization_id = i.organization_id
                AND drm.directory_group_id = i.directory_group_id
                AND drm.deleted IS FALSE
            )
          ELSE FALSE
        END
      ELSE
        CASE i.kind
          WHEN 'new_attribute_value' THEN
            EXISTS (
              SELECT 1 FROM directory_role_mappings AS drm
              WHERE drm.organization_id = i.organization_id
                AND drm.attribute_key = i.attribute_key
                AND drm.attribute_value = i.attribute_value
                AND drm.deleted IS FALSE
            )
            OR NOT EXISTS (
              SELECT 1 FROM directory_role_mappings AS drm
              WHERE drm.organization_id = i.organization_id
                AND drm.attribute_key = i.attribute_key
                AND drm.deleted IS FALSE
            )
            OR EXISTS (
              SELECT 1 FROM directory_review_attribute_opt_outs AS o
              WHERE o.organization_id = i.organization_id
                AND o.attribute_key = i.attribute_key
                AND o.deleted IS FALSE
            )
            OR NOT EXISTS (
              SELECT 1 FROM directory_users AS du
              WHERE du.organization_id = i.organization_id
                AND du.deleted IS FALSE
                AND du.workos_deleted IS FALSE
                AND du.attributes ->> i.attribute_key = i.attribute_value
            )
          WHEN 'source_missing' THEN
            EXISTS (
              SELECT 1 FROM directory_users AS du
              WHERE du.organization_id = i.organization_id
                AND du.deleted IS FALSE
                AND du.workos_deleted IS FALSE
                AND du.attributes ->> i.attribute_key = i.attribute_value
            )
            OR NOT EXISTS (
              SELECT 1 FROM directory_role_mappings AS drm
              WHERE drm.organization_id = i.organization_id
                AND drm.attribute_key = i.attribute_key
                AND drm.attribute_value = i.attribute_value
                AND drm.deleted IS FALSE
            )
          ELSE FALSE
        END
    END
  )
RETURNING i.id, i.organization_id, i.kind, i.directory_group_id, i.attribute_key, i.attribute_value, i.occurrence, i.state
`

type SupersedeDirectoryReviewItemsParams struct {
	OrganizationID   string
	DirectoryGroupID uuid.NullUUID
	AttributeKey     pgtype.Text
	AttributeValue   pgtype.Text
}

type SupersedeDirectoryReviewItemsRow struct {
	ID               uuid.UUID
	OrganizationID   string
	Kind             string
	DirectoryGroupID uuid.NullUUID
	AttributeKey     pgtype.Text
	AttributeValue   pgtype.Text
	Occurrence       int32
	State            string
}

// Settles pending items whose condition no longer holds. With no source
// filter it covers the whole organization, as the sweep does:
//
//	new_group: the group got a mapping or is gone.
//	new_attribute_value: the value got a mapping, nobody carries it, its key
//	  has no mapping left, or its key was opted out.
//	source_missing: the source is live again, or it has no mapping left.
func (q *Queries) SupersedeDirectoryReviewItems(ctx context.Context, arg SupersedeDirectoryReviewItemsParams) ([]SupersedeDirectoryReviewItemsRow, error) {
	rows, err := q.db.Query(ctx, supersedeDirectoryReviewItems,
		arg.OrganizationID,
		arg.DirectoryGroupID,
		arg.AttributeKey,
		arg.AttributeValue,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SupersedeDirectoryReviewItemsRow
	for rows.Next() {
		var i SupersedeDirectoryReviewItemsRow
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.Kind,
			&i.DirectoryGroupID,
			&i.AttributeKey,
			&i.AttributeValue,
			&i.Occurrence,
			&i.State,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
